BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (520::BIGINT, 'Resume bien la materia, al punto en el que uno va adelantado a otros grupos. Deja asignaciones que se nota son con el propósito de ayudar a los estudiantes. No califica duro,'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '8b9c2d7995cd99b66865868c12343143090654d0218b7c3c8558be74ced19e53'::TEXT, ARRAY[634]::BIGINT[]),
    (520::BIGINT, 'Gran profesor, ayuda muchísimo a los estudiantes que se esfuerzan, explica muy claro y atiende dudas. La clase es con folletos y apuntes digitales y si van bajos organiza una actividad final para levantar nota. Simplemente Parra, es un profe muy humano, muy recomendado 10/10.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '406b2c30a6cea8db22fdcc2820ac8ebc9c017393b896c57f76423e9fec4290ae'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'Excelente profesor, puede estudiar de su folleto y las prácticas de la cátedra y le irá súper bien. Recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3fb1d6d2be3258f937ed9de2db27a7e2c1e7dd156b7cba39e6ceec8feaf8d387'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'El sistema de evaluación diseñado para este curso es pedagógicamente ineficiente y no ofrece un margen real de mejora para el estudiante. Al asignarle un peso del 60% a los exámenes y un 40% a quices semanales que funcionan como pruebas cortas sin espacio a la retroalimentación, el curso castiga sev'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2026-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e2f6dd0d35a1a4a0be9a2612034394186dd6a6dc665ac609a69f712f4dbfc248'::TEXT, ARRAY[564]::BIGINT[]),
    (520::BIGINT, 'Es muy buen profesor y es super buena nota. Intenta explicar los más claro posible por lo que se toma la clase con calma y puede llegar a ser un poco aburrido. Los quices son sencillos, es muy flexible y super ordenado, además de que no califica duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '024949a2c9c97c1d2d2945641db032766677866298765468699cf48e3ca52cad'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'Hace que las clases son aburridas, explica muy lento se hacen solo como dos ejercicios por clase, aprendí más por mi cuenta que yendo a clase. Por otro lado los quices son muy fáciles 25% regalado si práctica antes.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '1ce972affcab5dd324b0ad17e6105f6f360e39fe90ebb0298cf8d16111dee80c'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'Es el goat. Es muy ordenado en cuanto que va a hacer cada clase y en general las clases las hace muy bien, explica la teoría y luego hace todas las prácticas del tema. Lo único que podría poner a mejorar (si acaso), es que tiene una voz bastante monótona entonces puede volverse aburrido. Un exc prof'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'f686e55f45e568091092511cdcab80496ce93c758233653318780dbe7cc72e23'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'Las clases se hacen largas y aburridas, pero el profesor es buena nota, brinda bastante ayuda y proporciona bastante material'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '7634467408931133bded63c80397bbee2b0283693929976dbe98f152945eb75b'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'el mae da buen material fuera de clases y se agraddece, pero explica super confuso y se para y medio'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2025-10-09T00:00:00+00:00'::TIMESTAMPTZ, '93943e6256cef1b68290b5fb9db8456d6122245141ea6befffbc1f1d4f96dc6d'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'El GOAT de Superior, sin duda, explica súper bien, hace nada más 3 quices bastante normales (nada muy duro) y 3 tareas (igualmente bastante simples), y califica muy muy suave, se pasa super bien el curso con él y se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Pocos exámenes']::TEXT[], '2025-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'ab99c2d2ab8f5a5e583065b766bf58c568e7edb54032083b4366ae3b9fecf481'::TEXT, ARRAY[923]::BIGINT[]),
    (520::BIGINT, 'A pesar de que califica algo duro, es un excelente profesor y es una gran adición a la escuela de matemáticas. Los quices son difíciles, pero en clases cubre todo, entonces los exámenes se pasan fácil.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '8c688dfe50b4c678b9521766e6196f0f12319b4a9f4172a8d909e3c4b29da8b8'::TEXT, ARRAY[923]::BIGINT[]),
    (520::BIGINT, 'Es un excelente profesor, explica muy claro y realmente se interesa porque el estudiante aprenda; siempre está muy anuente a explicar en consulta y es muy buena persona. Además, ayuda bastante con las evaluaciones si pones de tu parte y ve que te esfuerzas. Ultra recomendado para CDI.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, '46b529b980723059c5f51d7f970350b29825069598bc75ed309efea9e7a229ab'::TEXT, ARRAY[605]::BIGINT[]),
    (520::BIGINT, 'Excelente profesor, hizo mi experiencia en CDI muy gratificante. Logré aprender mucho con este profe. Súper amable también. Aunque el curso es difícil, es posible pasarlo aun sin tener mucho tiempo para estudiar (mi caso). Gracias a que con las clases uno aprende mucho, estudiar es muy liviano.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'ea11e959fb5deb45dee9ffabbc2705c99acddfb3c2261857b069a711fe5314c8'::TEXT, ARRAY[605]::BIGINT[]),
    (520::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f654c48376e319a9fee3c93438320a2d1444180c79f58ed8625bbb88b15fefa7'::TEXT, ARRAY[923]::BIGINT[]),
    (520::BIGINT, 'Muy buen profe, no tiene mucho rato en el TEC por lo que es poco conocido. Estudie los ejercicios que el hace en clase para prepararse para los quices, suelen ser con dificultad media/alta para prepararlo para los exámenes. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '9d7b77ccb0b4414084ed4a2e50c1d67f07d1e1c831eed1b92643b3326ad20620'::TEXT, ARRAY[923]::BIGINT[]),
    (520::BIGINT, 'Domina la materia, es muy amable, muy buena nota. Califica justo, además, aprecia su interés, casi siempre está disponible para consultas. Los quices hay que prepararse bien. En general muy buen profesor para proba, pero como consejo, estudie mucho también con exámenes viejos y cosas de catedra'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2f508bd04d5dae5afa2d7a090dbbdae72ac66150000e033081afc5b216a1e6ef'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'El profesor califica de manera justa, se preocupa por que el estudiante entienda y le vaya bien. Es mejor estudiar con examenes viejos o material de cátedra. Tareas sencillas pero quices un poco rudos. Excelente profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5f0c951e38afbf941c9d170924858dfd6ea65ff2cf6cd3b85efa2f0a37e0868e'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'El mejor profesor de matemática que hay en el TEC. Explica la materia de forma muy sencilla con ejemplos muy variados. Se le entiende a la perfección y tiene preparada la materia de todos los examenes para poder imprimirla y seguirla durante la clase. Califica justo. Solo prepárese bien para quizzes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f3755c9d92af097bf25cb649d2d321280745247babf5b43128a44e4a8d1eff86'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'El profesor domina excelente la materia y explica muy bien, pero explica cosas complejas que no se evalúan nunca en los exámenes. Califica justamente, y los quices y tareas son bastante claros. En general, siempre está dispuesto a ayudar. Si lleva con él estudie con material de cátedra mejor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-11-14T00:00:00+00:00'::TIMESTAMPTZ, '6f0cf130533105118885a9193ecc7d2301028e359c761675b511fbeb71ec02f1'::TEXT, ARRAY[1049]::BIGINT[]),
    (520::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2024-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'b1826845311948a8990f3b283d648e109935c3834a9c3450489c60177f814257'::TEXT, ARRAY[605]::BIGINT[]),
    (520::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '79d54dd9da3a682e4ebde3f1096abfd8ef673ce53441ab46e49041bf6b73a85d'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (520::BIGINT, 'Excelente Profesor, de los mejores de la escuela de Matemáticas, volvería a llevar con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-25T00:00:00+00:00'::TIMESTAMPTZ, '11ba5b2d02fe3aecaaf124b692a76b5e1d508355d1cb881c2486517806f9a150'::TEXT, ARRAY[605]::BIGINT[]),
    (520::BIGINT, 'Normal'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-05-03T00:00:00+00:00'::TIMESTAMPTZ, '1ec7066484089dbfcc22a9404e5721aad66076214ecf4b75911589020deefb00'::TEXT, ARRAY[923]::BIGINT[]),
    (520::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'e80cdc43c3c659390fccfcfc4144c21175a92913c89cc06efd7935dbae18258a'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
